INSERT INTO topics (id, chapter_id, topic_name, description, "order", required_tier) VALUES
  ('db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a86aff95-adbc-4634-af1f-528e375e2230', '3.7 Circular motion (extension)', 'Motion in a circle at constant speed: v = 2πr/T, a = v²/r and F = mv²/r, then vertical circles and conical pendulums. Extension material — the Cambridge IGCSE 0625 core (3.3) only asks for the direction of the force; this is standard groundwork for AS/A Level and AP Physics.', 7, 0),
  ('1585a36a-5b5c-5505-abe3-98e37e28c48b', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '24.3 Gravitation and orbits (extension)', 'Newton’s law of gravitation, F = Gm₁m₂/r², and circular orbits: field strength, orbital speed, period and the mass of a planet from an orbit. Extension material beyond the Cambridge IGCSE 0625 core, following on from 24.2 The Solar System.', 3, 0)
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a36e834f-af06-543c-8cf1-3a6855e17bb1', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 1, 1, 'A race car makes one lap around a circular track of radius 50 m in 9.0 s. Calculate the car’s average speed, in m/s.', 'diagram:circular-horizontal', 1, 'numeric'::answer_type, '34.91', 'm/s', NULL, false, 'One lap is one circumference, so v = 2πr/T = (2π × 50) ÷ 9.0 = 34.9 m/s. (Its average velocity over a whole lap is actually zero — it ends where it started — which is why the question asks for speed.)', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6e9b4b89-1b80-5ea9-9b47-250751471341', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 2, 2, 'The same race car goes round the 50 m radius track once every 9.0 s. Calculate its centripetal acceleration, in m/s².', NULL, 2, 'numeric'::answer_type, '24.37', 'm/s²', NULL, false, 'First the speed: v = 2πr/T = (2π × 50) ÷ 9.0 = 34.9 m/s. Then a = v²/r = 34.9² ÷ 50 = 24.4 m/s², directed towards the centre of the track.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f48b8369-9b37-5e59-8b79-532609aaa426', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 3, 3, 'Normie Neutron swings a rubber ball on a string over his head in a horizontal circle. The string is 1.5 m long and the ball makes 120 complete turns each minute. Calculate the speed of the ball, in m/s.', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '18.85', 'm/s', NULL, false, '120 turns per minute is 2 turns per second, so the period is T = 60 ÷ 120 = 0.50 s. The radius is the string length, 1.5 m. v = 2πr/T = (2π × 1.5) ÷ 0.50 = 18.8 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('93d0b5de-cf15-5f05-8c30-15b6fdfc67ba', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 4, 4, 'Normie Neutron’s ball moves in a horizontal circle of radius 1.5 m, making 120 complete turns each minute. Calculate the ball’s centripetal acceleration, in m/s².', NULL, 2, 'numeric'::answer_type, '236.9', 'm/s²', NULL, false, 'T = 60 ÷ 120 = 0.50 s, so v = 2πr/T = 18.8 m/s. Then a = v²/r = 18.8² ÷ 1.5 = 237 m/s². (Or in one step: a = 4π²r/T² = 4π² × 1.5 ÷ 0.50² = 237 m/s².)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ebddb66d-cd54-54b6-93b7-ee5a544f2bff', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 5, 5, 'A car goes around a curve at 20 m/s. The radius of the curve is 50 m. Calculate the centripetal acceleration of the car, in m/s².', NULL, 1, 'numeric'::answer_type, '8', 'm/s²', NULL, false, 'a = v²/r = 20² ÷ 50 = 400 ÷ 50 = 8.0 m/s², towards the centre of the curve.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1a45349b-45c7-58bf-803a-586ec2c82155', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 6, 6, 'Professor Brown holds on to the end of the minute hand of a clock on top of the city hall. The minute hand is 4.0 m long. Calculate the professor’s centripetal acceleration, in m/s².', NULL, 3, 'numeric'::answer_type, '1.218e-5', 'm/s²', 0.05, false, 'The minute hand goes round once an hour, so T = 3600 s, and the radius is its length, 4.0 m. a = 4π²r/T² = (4π² × 4.0) ÷ 3600² = 1.22 × 10⁻⁵ m/s² — tiny, because the hand turns so slowly.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ade166f8-f356-5663-a435-36d38131dfa3', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 7, 7, 'A flea rides on the outer edge of a record of radius 15 cm. The record turns once every 1.8 s. Calculate the flea’s speed, in m/s.', NULL, 2, 'numeric'::answer_type, '0.5236', 'm/s', NULL, false, 'Convert the radius to metres first: 15 cm = 0.15 m. v = 2πr/T = (2π × 0.15) ÷ 1.8 = 0.524 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d81e7c82-f465-5077-a1f4-86b28aa594f6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 8, 8, 'The flea on the edge of the 15 cm radius record goes round once every 1.8 s. Calculate its centripetal acceleration, in m/s².', NULL, 2, 'numeric'::answer_type, '1.828', 'm/s²', NULL, false, 'v = 2πr/T = (2π × 0.15) ÷ 1.8 = 0.524 m/s, so a = v²/r = 0.524² ÷ 0.15 = 1.83 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('33ffe534-d8a9-5741-b541-758f291cb05c', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 9, 9, 'A bicycle wheel has a radius of 0.35 m. A point on the rim moves at 8.0 m/s. Calculate the period of rotation of the wheel, in seconds.', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '0.2749', 's', NULL, false, 'Rearrange v = 2πr/T to T = 2πr/v = (2π × 0.35) ÷ 8.0 = 0.275 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('158ffd84-7662-5fc2-8a56-7fcf68162427', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 10, 10, 'A 900 kg car rounds a flat, circular curve of radius 50 m at a constant speed of 15 m/s. Calculate the magnitude of the car’s centripetal acceleration, in m/s².', 'diagram:circular-horizontal', 1, 'numeric'::answer_type, '4.5', 'm/s²', NULL, false, 'a = v²/r = 15² ÷ 50 = 225 ÷ 50 = 4.5 m/s². The car’s mass is not needed for the acceleration — only for the force.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0573baf0-9604-56e5-8674-247982dcf677', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 11, 11, 'A steel beam rotates in a horizontal circle to give trainee pilots a large centripetal acceleration. A pilot sits 2.0 m from the centre of rotation. At what speed must the pilot move to experience a centripetal acceleration of 78 m/s²?', NULL, 2, 'numeric'::answer_type, '12.49', 'm/s', NULL, false, 'Rearrange a = v²/r: v = √(a × r) = √(78 × 2.0) = √156 = 12.5 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('13a5f815-3ce3-5443-8e2a-c9d6a3d73334', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 12, 12, 'A 0.20 kg mass is spun in a horizontal circle on a string 0.60 m long. Its centripetal acceleration is measured to be 15 m/s². Calculate the speed of the mass, in m/s.', 'diagram:circular-horizontal', 1, 'numeric'::answer_type, '3', 'm/s', NULL, false, 'The string length is the radius, 0.60 m. v = √(a × r) = √(15 × 0.60) = √9.0 = 3.0 m/s. The mass does not affect the answer.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2096fe55-c83c-5e58-87ac-5b938441fb08', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 13, 13, 'A 0.75 kg object on a string is swung in a horizontal circle of radius 1.1 m. It completes 12 revolutions every minute. Calculate the tension in the string, which provides the centripetal force, in newtons.', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '1.303', 'N', NULL, false, '12 revolutions per minute gives T = 60 ÷ 12 = 5.0 s. F = m × 4π²r/T² = 0.75 × 4π² × 1.1 ÷ 5.0² = 1.30 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6ff04b22-c150-57b2-a976-b62f61e3bfc7', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 14, 14, 'A 25 kg child on a merry-go-round feels a centripetal force of 50 N. The merry-go-round has a period of 4.0 s. Calculate the radius of the child’s path, in metres.', 'diagram:circular-horizontal', 3, 'numeric'::answer_type, '0.8106', 'm', NULL, false, 'Rearrange F = m × 4π²r/T² for r: r = F T²/(4π² m) = (50 × 4.0²) ÷ (4π² × 25) = 800 ÷ 987 = 0.811 m.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4d5e65d7-dece-5529-88df-e14210d92a6e', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 15, 15, 'A 0.100 kg mass on a string 75 cm long swings in a horizontal circle, going round once every 0.80 s. Calculate the centripetal acceleration of the mass, in m/s².', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '46.26', 'm/s²', NULL, false, 'r = 75 cm = 0.75 m and T = 0.80 s. a = 4π²r/T² = 4π² × 0.75 ÷ 0.80² = 46.3 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9094d8d0-c75f-508b-b5f3-1c92a30c6266', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 16, 16, 'The 0.100 kg mass on a 75 cm string goes round its horizontal circle once every 0.80 s. Calculate the tension in the string, in newtons.', NULL, 2, 'numeric'::answer_type, '4.626', 'N', NULL, false, 'The tension provides the centripetal force. a = 4π²r/T² = 46.3 m/s², so T = m a = 0.100 × 46.3 = 4.63 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('44284e44-b6cc-5ad0-835f-c504712c8cc3', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 17, 17, 'A 0.50 kg mass on a string 1.0 m long moves in a horizontal circle, completing one revolution every 0.50 s. Calculate the centripetal acceleration of the mass, in m/s².', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '157.9', 'm/s²', NULL, false, 'a = 4π²r/T² = 4π² × 1.0 ÷ 0.50² = 158 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dd7e3dab-c23e-5d41-8054-1da480e054db', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 18, 18, 'The 0.50 kg mass on a 1.0 m string completes one horizontal revolution every 0.50 s. Calculate the tension in the string, in newtons.', NULL, 2, 'numeric'::answer_type, '78.96', 'N', NULL, false, 'a = 4π²r/T² = 158 m/s², and the tension supplies the centripetal force: F = m a = 0.50 × 158 = 79.0 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8f7f75bd-0c59-58dd-b466-045ca9075d04', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 19, 19, 'A 900 kg racing car takes 12.3 s to go once around a circular racetrack of radius 90.0 m at a uniform speed. Calculate the centripetal force acting on the car, in newtons.', 'diagram:circular-horizontal', 3, 'numeric'::answer_type, '21137', 'N', NULL, false, 'F = m × 4π²r/T² = 900 × 4π² × 90.0 ÷ 12.3² = 21100 N. (Equivalently, v = 2πr/T = 46.0 m/s and F = mv²/r.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cc7ee32a-08c0-509c-ad05-976b16ca1519', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 20, 20, 'A racing car drives round a flat circular track at a steady speed. Which force provides the centripetal force that keeps it on the circle?', NULL, 1, 'multiple_choice'::answer_type, 'Friction between the tyres and the road', NULL, NULL, false, 'On a flat track the only horizontal force that can point towards the centre is the sideways friction between the tyres and the road. Weight acts downwards, the engine’s driving force acts forwards and air resistance acts backwards — none of them points towards the centre.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('af546063-941a-5b0b-b4d1-0c3046ba1529', 'cc7ee32a-08c0-509c-ad05-976b16ca1519', 'Friction between the tyres and the road', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('de471b4f-eefb-5d44-ab78-691ad03db3d5', 'cc7ee32a-08c0-509c-ad05-976b16ca1519', 'The weight of the car', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4dc5dfc6-7d0c-54fc-8d19-e3dced8661d6', 'cc7ee32a-08c0-509c-ad05-976b16ca1519', 'The driving force from the engine', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d0fc1e78-80b7-5aef-94b8-576348b7808b', 'cc7ee32a-08c0-509c-ad05-976b16ca1519', 'Air resistance', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('19f7d812-5e12-5e3f-8d93-ecc2ef7eafc8', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 21, 21, 'A 2.0 kg object tied to a cord is whirled in a horizontal circle of radius 4.0 m, completing 2 revolutions every 6.0 s. Calculate the speed of the object, in m/s.', 'diagram:circular-horizontal', 2, 'numeric'::answer_type, '8.378', 'm/s', NULL, false, '2 revolutions in 6.0 s means one every 3.0 s, so T = 3.0 s. v = 2πr/T = (2π × 4.0) ÷ 3.0 = 8.38 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2d8c24a9-8732-5c8a-890e-616e2e545349', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 22, 22, 'The 2.0 kg object whirls round a horizontal circle of radius 4.0 m, completing 2 revolutions every 6.0 s. Calculate its centripetal acceleration, in m/s².', NULL, 2, 'numeric'::answer_type, '17.55', 'm/s²', NULL, false, 'T = 3.0 s, so v = 2πr/T = 8.38 m/s and a = v²/r = 8.38² ÷ 4.0 = 17.5 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7e509387-b7ff-5115-92a1-17c4c46b34cb', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 23, 23, 'The 2.0 kg object whirls round a horizontal circle of radius 4.0 m, completing 2 revolutions every 6.0 s. Calculate the pull (tension) in the cord, in newtons.', NULL, 2, 'numeric'::answer_type, '35.09', 'N', NULL, false, 'The cord’s pull is the centripetal force. a = 17.5 m/s² (from v = 8.38 m/s and a = v²/r), so F = m a = 2.0 × 17.5 = 35.1 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b62665c7-ff9d-53dc-90c3-1db218a151ce', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 24, 24, 'An object is being whirled in a horizontal circle on a cord when the cord suddenly breaks. What does the object do immediately afterwards?', NULL, 1, 'multiple_choice'::answer_type, 'It moves off in a straight line along the tangent to the circle', NULL, NULL, false, 'Once the cord breaks there is no longer a centripetal force, so (ignoring gravity) no force changes the object’s direction. It keeps the velocity it had at that instant, and that velocity points along the tangent — so it flies off in a straight line at a tangent, at the speed it was already moving.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ec75a570-295f-5b95-bb1e-911de6e717ab', 'b62665c7-ff9d-53dc-90c3-1db218a151ce', 'It moves off in a straight line along the tangent to the circle', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3a599b83-9abd-5e5d-b531-9c681d1d5dae', 'b62665c7-ff9d-53dc-90c3-1db218a151ce', 'It moves straight outwards, directly away from the centre', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d3c6493a-6210-5844-848b-f27385876e6e', 'b62665c7-ff9d-53dc-90c3-1db218a151ce', 'It carries on moving round the same circle', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ce577397-e6dd-5151-ae21-c579375b4fa0', 'b62665c7-ff9d-53dc-90c3-1db218a151ce', 'It moves straight towards the centre of the circle', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fe2f094c-d2f8-5621-b81d-0371af1cadad', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 25, 25, 'A 0.50 kg mass on a string 0.90 m long is swung in a vertical circle, taking 1.8 s for each revolution. Treating its speed as constant, calculate the tension in the string at the bottom of the circle, in newtons. Take g = 9.8 m/s².', 'diagram:circular-vertical-bottom', 3, 'numeric'::answer_type, '10.38', 'N', 0.05, false, 'v = 2πr/T = (2π × 0.90) ÷ 1.8 = 3.14 m/s. At the bottom the tension pulls up (towards the centre) and the weight pulls down, and their difference provides the centripetal force: T − mg = mv²/r. So T = m(g + v²/r) = 0.50 × (9.8 + 3.14² ÷ 0.90) = 0.50 × (9.8 + 11.0) = 10.4 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a0cf72c5-c8c2-50c9-a60f-f8cb1cf3eb0d', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 26, 26, 'A 2.1 kg object is swung on the end of a 1.2 m string in a vertical circle, taking 1.5 s for each revolution. Treating its speed as constant, calculate the tension in the string at the top of the circle, in newtons. Take g = 9.8 m/s².', 'diagram:circular-vertical-top', 3, 'numeric'::answer_type, '23.64', 'N', 0.05, false, 'The centripetal acceleration is a = 4π²r/T² = 4π² × 1.2 ÷ 1.5² = 21.1 m/s². At the top both the tension and the weight point down, towards the centre: T + mg = ma. So T = m(a − g) = 2.1 × (21.1 − 9.8) = 23.6 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c603c74b-5689-56fc-a67b-88f0529cbc8e', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 27, 27, 'A roller coaster car goes round a vertical loop of radius 7.5 m. Calculate the minimum speed the car needs at the top of the loop so that it does not lose contact with the track, in m/s. Take g = 9.8 m/s².', 'diagram:circular-vertical-top', 3, 'numeric'::answer_type, '8.573', 'm/s', 0.05, false, 'At the minimum speed the track pushes with zero force at the top, so the weight alone provides the centripetal force: mg = mv²/r. The mass cancels, leaving v = √(g r) = √(9.8 × 7.5) = 8.57 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8d89f9ed-1af7-5fe6-8ce4-1ed34ffd6081', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 28, 28, 'A 4.0 kg bucket of water is swung in a vertical circle of radius 1.5 m. Its speed at the bottom of the circle is 5.0 m/s. Calculate the tension in the rope at the bottom, in newtons. Take g = 9.8 m/s².', 'diagram:circular-vertical-bottom', 3, 'numeric'::answer_type, '105.9', 'N', 0.05, false, 'At the bottom, T − mg = mv²/r, so T = m(g + v²/r) = 4.0 × (9.8 + 5.0² ÷ 1.5) = 4.0 × (9.8 + 16.7) = 106 N — much more than the bucket’s weight of 39 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3c2e9d8c-332a-576c-83e0-19f547247393', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 29, 29, 'An astronaut in a centrifuge moves round a vertical circle of radius 12.0 m. Calculate the minimum speed at the top of the circle that gives apparent weightlessness (zero normal force), in m/s. Take g = 9.8 m/s².', 'diagram:circular-vertical-top', 3, 'numeric'::answer_type, '10.84', 'm/s', 0.05, false, 'With zero normal force, the weight alone provides the centripetal force at the top: mg = mv²/r, so v = √(g r) = √(9.8 × 12.0) = 10.8 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('efb8206b-7b1a-5a0e-a15b-589bcc9f556f', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 30, 30, 'A 0.50 kg ball on a 1.5 m string is swung in a horizontal circle, so that the string makes an angle of 35° with the vertical. Calculate the tension in the string, in newtons. Take g = 9.8 m/s².', 'diagram:circular-conical', 3, 'numeric'::answer_type, '5.982', 'N', 0.05, false, 'The ball does not rise or fall, so the vertical component of the tension balances its weight: T cos35° = mg. T = mg ÷ cos35° = (0.50 × 9.8) ÷ 0.819 = 5.98 N. (The string length is not needed.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c142d009-826c-5e43-b4c8-46409167f5dd', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 31, 31, 'A conical pendulum has a string 0.90 m long, which makes an angle of 25° with the vertical. Calculate the speed of the mass, in m/s. Take g = 9.8 m/s².', 'diagram:circular-conical', 4, 'numeric'::answer_type, '1.318', 'm/s', 0.05, false, 'The radius of the circle is r = L sin25° = 0.90 × 0.423 = 0.380 m. Vertically T cos25° = mg; horizontally T sin25° = mv²/r. Dividing gives tan25° = v²/(r g), so v = √(r g tan25°) = √(0.380 × 9.8 × 0.466) = 1.32 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4d44b3d-9732-58b7-b084-a139b95da930', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 32, 32, 'A 2.0 kg object swings as a conical pendulum. The tension in the string is 30 N. Calculate the angle θ that the string makes with the vertical, in degrees. Take g = 9.8 m/s².', 'diagram:circular-conical', 3, 'numeric'::answer_type, '49.21', '°', 0.05, false, 'Vertically the forces balance: T cosθ = mg, so cosθ = mg/T = (2.0 × 9.8) ÷ 30 = 0.653. θ = cos⁻¹(0.653) = 49.2°.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2575ab77-cfa6-513c-92a4-64c8b06ce11a', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 33, 33, 'The mass on a conical pendulum moves round a circle of radius 0.45 m at a speed of 3.0 m/s. Calculate the period of rotation, in seconds.', 'diagram:circular-conical', 2, 'numeric'::answer_type, '0.9425', 's', NULL, false, 'T = 2πr/v = (2π × 0.45) ÷ 3.0 = 0.942 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('508ef80c-b48b-55dd-b55f-82178dc52c05', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 34, 34, 'A conical pendulum has a period of 2.2 s and the mass moves round a circle of radius 0.70 m. Calculate the angle θ that the string makes with the vertical, in degrees. Take g = 9.8 m/s².', 'diagram:circular-conical', 4, 'numeric'::answer_type, '30.23', '°', 0.05, false, 'The centripetal acceleration is a = 4π²r/T² = 4π² × 0.70 ÷ 2.2² = 5.71 m/s². For a conical pendulum tanθ = a/g (horizontal T sinθ = ma, vertical T cosθ = mg), so tanθ = 5.71 ÷ 9.8 = 0.583 and θ = 30.2°.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c09f2ec6-3bf7-5a74-a1b3-83cb9e6fecb5', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 35, 35, 'A 0.25 kg toy plane on a string flies in a horizontal circle of radius 0.80 m. The string makes an angle of 28° with the vertical. Calculate the period of rotation, in seconds. Take g = 9.8 m/s².', 'diagram:circular-conical', 4, 'numeric'::answer_type, '2.462', 's', 0.05, false, 'Weight: mg = 0.25 × 9.8 = 2.45 N. The tension’s vertical part balances the weight and its horizontal part is the centripetal force, so tan28° = Fc/mg and Fc = 2.45 × tan28° = 2.45 × 0.532 = 1.30 N. Then Fc = m × 4π²r/T² gives T = √(m × 4π²r ÷ Fc) = √(0.25 × 4π² × 0.80 ÷ 1.30) = 2.46 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('40f597a1-79ab-5a3b-a756-94ef58c50b5b', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 1, 1, 'Calculate the gravitational field strength on the surface of a planet with a mass of 5.0 × 10²³ kg and a radius of 4.0 × 10⁶ m, in N/kg. Use G = 6.67 × 10⁻¹¹ N·m²/kg².', NULL, 2, 'numeric'::answer_type, '2.084', 'N/kg', 0.05, false, 'g = GM/R² = (6.67 × 10⁻¹¹ × 5.0 × 10²³) ÷ (4.0 × 10⁶)² = 3.33 × 10¹³ ÷ 1.60 × 10¹³ = 2.08 N/kg — about a fifth of the value on Earth.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('35209066-54a6-57ca-9925-68b9e0f8f891', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 2, 2, 'Two asteroids, of masses 5.0 × 10¹² kg and 7.5 × 10¹² kg, are 3500 m apart. Calculate the gravitational force between them, in newtons. Use G = 6.67 × 10⁻¹¹ N·m²/kg².', 'diagram:gravity-two-bodies', 2, 'numeric'::answer_type, '2.042e8', 'N', 0.05, false, 'F = G m₁m₂/r² = (6.67 × 10⁻¹¹ × 5.0 × 10¹² × 7.5 × 10¹²) ÷ 3500² = 2.50 × 10¹⁵ ÷ 1.23 × 10⁷ = 2.04 × 10⁸ N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ddfa779f-68ae-5c6a-9195-32c227476c3c', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 3, 3, 'A weather satellite orbits the Earth at an orbital radius of 4.0 × 10⁷ m. Calculate its orbital speed, in m/s. Use G = 6.67 × 10⁻¹¹ N·m²/kg² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:gravity-orbit', 3, 'numeric'::answer_type, '3155', 'm/s', 0.05, false, 'Gravity provides the centripetal force: GMm/r² = mv²/r, so v = √(GM/r) = √(6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 4.0 × 10⁷) = √(9.95 × 10⁶) = 3160 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d40154e9-a2f3-5ca2-b709-b9ec47ea7b02', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 4, 4, 'A communications satellite orbits the Earth with a period of 8.0 × 10⁴ s. Calculate its orbital radius, in metres. Use G = 6.67 × 10⁻¹¹ N·m²/kg² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:gravity-orbit', 4, 'numeric'::answer_type, '4.012e7', 'm', 0.05, false, 'Gravity provides the centripetal force: GMm/r² = m × 4π²r/T², so r³ = GMT²/(4π²) = (6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × (8.0 × 10⁴)²) ÷ 4π² = 6.46 × 10²² m³. Taking the cube root, r = 4.01 × 10⁷ m.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('71bacdf7-1cbe-51b7-b0f0-654cd3e513a2', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 5, 5, 'A probe orbits Jupiter (mass 1.90 × 10²⁷ kg) at a radius of 1.0 × 10⁸ m. Calculate the orbital period of the probe, in seconds. Use G = 6.67 × 10⁻¹¹ N·m²/kg².', 'diagram:gravity-orbit', 4, 'numeric'::answer_type, '17650', 's', 0.05, false, 'From GMm/r² = m × 4π²r/T², T = 2π√(r³/GM) = 2π√((1.0 × 10⁸)³ ÷ (6.67 × 10⁻¹¹ × 1.90 × 10²⁷)) = 2π × 2810 = 17600 s — about 4.9 hours.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6718a972-47df-573c-9dc0-6a43b633ee48', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 6, 6, 'A spaceship goes into a circular orbit around a planet at a height of 351 km above the surface, with a period of 5.46 × 10³ s. The planet has a radius of 5220 km. Calculate the mass of the planet, in kg. Use G = 6.67 × 10⁻¹¹ N·m²/kg².', 'diagram:gravity-orbit', 5, 'numeric'::answer_type, '3.433e24', 'kg', 0.05, false, 'The orbital radius is measured from the planet’s centre: r = 5220 km + 351 km = 5571 km = 5.571 × 10⁶ m. From GMm/r² = m × 4π²r/T², M = 4π²r³/(GT²) = 4π² × (5.571 × 10⁶)³ ÷ (6.67 × 10⁻¹¹ × (5.46 × 10³)²) = 3.43 × 10²⁴ kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9eaeeaec-3967-56fa-9b11-896f3aa86df1', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 7, 7, 'Phobos, one of the moons of Mars, orbits at a mean radius of 9.38 × 10⁶ m with a period of 2.76 × 10⁴ s. Calculate the mass of Mars, in kg. Use G = 6.67 × 10⁻¹¹ N·m²/kg².', 'diagram:gravity-orbit', 4, 'numeric'::answer_type, '6.412e23', 'kg', 0.05, false, 'Gravity provides Phobos’s centripetal force: GMm/r² = m × 4π²r/T², so M = 4π²r³/(GT²) = 4π² × (9.38 × 10⁶)³ ÷ (6.67 × 10⁻¹¹ × (2.76 × 10⁴)²) = 6.41 × 10²³ kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0512b765-12fe-5543-9555-0cf6b4b943f7', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 42, 42, 'Three charges are arranged in an L-shape, as shown. q₁ = +2.0 × 10⁻⁶ C is at the origin, q₂ = −3.0 × 10⁻⁶ C is on the x-axis 0.40 m from q₁, and q₃ = +1.0 × 10⁻⁶ C is on the y-axis 0.30 m from q₁. Calculate the magnitude of the net electrostatic force on q₁, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-l-shape-origin', 3, 'numeric'::answer_type, '0.3923', 'N', 0.05, false, 'q₂ has the opposite sign, so it attracts q₁ along +x: F₁₂ = (9.0 × 10⁹ × 2.0 × 10⁻⁶ × 3.0 × 10⁻⁶) ÷ 0.40² = 0.337 N. q₃ has the same sign, so it repels q₁ along −y: F₁₃ = (9.0 × 10⁹ × 2.0 × 10⁻⁶ × 1.0 × 10⁻⁶) ÷ 0.30² = 0.200 N. The two are at right angles: F = √(0.337² + 0.200²) = 0.392 N, directed 30.7° below the +x axis.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b4d887e7-69d2-5eba-a3b1-6b9a0ea62aee', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 43, 43, 'Charge qA = +5.0 mC is at (0, 0), qB = −8.0 mC is at (3.0 m, 0) and qC = +1.0 mC is at (0, 4.0 m), as shown. Calculate the magnitude of the net electrostatic force on qA, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-l-shape-millicoulomb', 3, 'numeric'::answer_type, '40099', 'N', 0.05, false, '1 mC = 1.0 × 10⁻³ C. qB attracts qA along +x: F = (9.0 × 10⁹ × 5.0 × 10⁻³ × 8.0 × 10⁻³) ÷ 3.0² = 40000 N. qC repels qA along −y: F = (9.0 × 10⁹ × 5.0 × 10⁻³ × 1.0 × 10⁻³) ÷ 4.0² = 2810 N. Net force = √(40000² + 2810²) = 40100 N, pointing 4.0° below the +x axis.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('58c65f2b-be83-5a96-98f8-2cdd61e0e1d8', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 44, 44, 'Two charges, qa = −4.0 × 10⁻⁹ C and qb = +5.0 × 10⁻⁹ C, are 0.20 m apart. A third charge, qc = +2.0 × 10⁻⁹ C, sits 0.10 m from qa so that the three form a right-angled triangle with the right angle at qa, as shown. Calculate the magnitude of the net electrostatic force on qc, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-l-shape-nanocoulomb', 4, 'numeric'::answer_type, '6.595e-6', 'N', 0.05, false, 'qa attracts qc straight towards qa: F = (9.0 × 10⁹ × 2.0 × 10⁻⁹ × 4.0 × 10⁻⁹) ÷ 0.10² = 7.20 × 10⁻⁶ N. qc is √(0.20² + 0.10²) = 0.224 m from qb, which repels it along the line from qb to qc: F = (9.0 × 10⁹ × 2.0 × 10⁻⁹ × 5.0 × 10⁻⁹) ÷ 0.050 = 1.80 × 10⁻⁶ N. These are NOT at right angles, so resolve: the qb force has components 1.61 × 10⁻⁶ N away from qb (parallel to qa–qb) and 8.05 × 10⁻⁷ N away from qa. Net: 1.61 × 10⁻⁶ N sideways and 6.40 × 10⁻⁶ N towards qa, so F = 6.59 × 10⁻⁶ N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b80ec98b-eee6-5d03-9f4d-e2171a0f35dc', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 45, 45, 'Charge qx = +10 nC is at the origin. qy = +5.0 nC is 1.0 m to its right on the x-axis, and qz = −10 nC is 1.0 m directly above it on the y-axis, as shown. Calculate the magnitude of the net force on qx, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-l-shape-unit', 3, 'numeric'::answer_type, '1.006e-6', 'N', 0.05, false, '1 nC = 1.0 × 10⁻⁹ C. qy repels qx to the left: F = (9.0 × 10⁹ × 10 × 10⁻⁹ × 5.0 × 10⁻⁹) ÷ 1.0² = 4.50 × 10⁻⁷ N. qz attracts qx upwards: F = (9.0 × 10⁹ × 10 × 10⁻⁹ × 10 × 10⁻⁹) ÷ 1.0² = 9.00 × 10⁻⁷ N. Net = √((4.50 × 10⁻⁷)² + (9.00 × 10⁻⁷)²) = 1.01 × 10⁻⁶ N, pointing up and to the left, 26.6° from the vertical.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0a375531-e67d-50f4-abf3-4d23326d9d20', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 46, 46, 'Three charges sit at the corners of an equilateral triangle of side 0.50 m, as shown: qA = +4.0 µC, qB = −6.0 µC and qC = +2.0 µC. Calculate the magnitude of the net electrostatic force on qC, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-equilateral', 4, 'numeric'::answer_type, '0.381', 'N', 0.05, false, '1 µC = 1.0 × 10⁻⁶ C. qA repels qC along the line A→C: F = (9.0 × 10⁹ × 4.0 × 10⁻⁶ × 2.0 × 10⁻⁶) ÷ 0.50² = 0.288 N. qB attracts qC along the line C→B: F = (9.0 × 10⁹ × 6.0 × 10⁻⁶ × 2.0 × 10⁻⁶) ÷ 0.50² = 0.432 N. Each line is at 60° to the base. Horizontal components add: (0.288 + 0.432) × cos60° = 0.360 N. Vertical components oppose: (0.432 − 0.288) × sin60° = 0.125 N downwards. Net F = √(0.360² + 0.125²) = 0.381 N, pointing 19.1° below the direction from qA to qB.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f4a5865f-a2f8-56d3-a585-dd7b2688d81c', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 47, 47, 'q₁ = +8.0 nC is at the origin and q₂ = −5.0 nC is on the x-axis at (0.30 m, 0). q₃ = +6.0 nC is 0.50 m from q₁ and 0.70 m from q₂, as shown. Calculate the magnitude of the net electrostatic force on q₂, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-triangle-scalene', 4, 'numeric'::answer_type, '4.446e-6', 'N', 0.05, false, 'q₁ attracts q₂ along −x: F = (9.0 × 10⁹ × 8.0 × 10⁻⁹ × 5.0 × 10⁻⁹) ÷ 0.30² = 4.00 × 10⁻⁶ N. q₃ attracts q₂ towards q₃: F = (9.0 × 10⁹ × 6.0 × 10⁻⁹ × 5.0 × 10⁻⁹) ÷ 0.70² = 5.51 × 10⁻⁷ N. Solving for q₃’s position (x² + y² = 0.50², (x − 0.30)² + y² = 0.70²) puts it at (−0.25 m, 0.433 m), so the line from q₂ to q₃ makes 38.2° with the −x direction. Components: x = −4.00 × 10⁻⁶ − 5.51 × 10⁻⁷ × 0.786 = −4.43 × 10⁻⁶ N; y = 5.51 × 10⁻⁷ × 0.619 = 3.41 × 10⁻⁷ N. F = 4.45 × 10⁻⁶ N, at 176° to the +x axis.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0e715f3e-c181-5009-906f-9fdc2fa2c43e', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 48, 48, 'Two point charges, q₁ = +5.0 × 10⁻⁶ C and q₂ = +8.0 × 10⁻⁶ C, repel each other with a force of 0.90 N. Calculate the distance between them, in metres. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '0.6325', 'm', NULL, false, 'Rearrange F = kq₁q₂/r²: r = √(kq₁q₂/F) = √(9.0 × 10⁹ × 5.0 × 10⁻⁶ × 8.0 × 10⁻⁶ ÷ 0.90) = √0.400 = 0.632 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('99a42289-5bd6-5530-b764-c30d96a032a7', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 49, 49, 'An electron (charge −1.60 × 10⁻¹⁹ C) and a proton (charge +1.60 × 10⁻¹⁹ C) attract each other with a force of 2.0 × 10⁻⁸ N. Calculate their separation, in metres. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 3, 'numeric'::answer_type, '1.073e-10', 'm', 0.05, false, 'r = √(k|q₁q₂|/F) = √(9.0 × 10⁹ × (1.60 × 10⁻¹⁹)² ÷ 2.0 × 10⁻⁸) = √(1.15 × 10⁻²⁰) = 1.07 × 10⁻¹⁰ m — about the size of an atom.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5018f20e-e010-5faf-a519-0693341b88ac', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 50, 50, 'Two oppositely charged spheres, carrying charges of magnitude 1.0 mC and 2.0 mC, attract each other with a force of 1.5 N. Calculate the distance between their centres, in metres. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '109.5', 'm', NULL, false, '1 mC = 1.0 × 10⁻³ C. r = √(k|q₁q₂|/F) = √(9.0 × 10⁹ × 1.0 × 10⁻³ × 2.0 × 10⁻³ ÷ 1.5) = √12000 = 110 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('002fbafe-6c3d-5a41-81ca-3ac005377b48', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 51, 51, 'Two identical small metal spheres each carry a charge of −4.0 nC. They repel each other with a force of 5.0 × 10⁻⁴ N. How far apart are they, in metres? Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '0.01697', 'm', NULL, false, '1 nC = 1.0 × 10⁻⁹ C. r = √(kq²/F) = √(9.0 × 10⁹ × (4.0 × 10⁻⁹)² ÷ 5.0 × 10⁻⁴) = √(2.88 × 10⁻⁴) = 0.0170 m, or about 1.7 cm.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4a4d19e3-f975-5ddc-8269-7ed197a3aa5d', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 52, 52, 'A charge of 25 mC exerts a force of 1000 N on a second charge of 5.0 mC. Calculate the distance between the two charges, in metres. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '33.54', 'm', NULL, false, 'r = √(kq₁q₂/F) = √(9.0 × 10⁹ × 25 × 10⁻³ × 5.0 × 10⁻³ ÷ 1000) = √1125 = 33.5 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3a78ac74-3677-5ec7-b768-ecea28ef5fe7', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 53, 53, 'A point charge q₁ = +3.0 mC is 0.50 m from a second charge q₂. The attractive force between them is 0.27 N. Calculate the magnitude of q₂, in coulombs. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '2.5e-9', 'C', NULL, false, 'Rearrange F = kq₁q₂/r²: q₂ = F r²/(k q₁) = (0.27 × 0.50²) ÷ (9.0 × 10⁹ × 3.0 × 10⁻³) = 0.0675 ÷ 2.70 × 10⁷ = 2.50 × 10⁻⁹ C (2.5 nC). It must be negative, since the force is attractive.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('24d4feee-ae9a-55b8-9386-e2c89324026c', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 54, 54, 'Two charges are 1.0 m apart. One of them is +4.0 × 10⁻⁵ C, and the repulsive force between them is 1.08 N. Calculate the magnitude of the second charge, in coulombs. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 2, 'numeric'::answer_type, '3e-6', 'C', NULL, false, 'q₂ = F r²/(k q₁) = (1.08 × 1.0²) ÷ (9.0 × 10⁹ × 4.0 × 10⁻⁵) = 1.08 ÷ 3.60 × 10⁵ = 3.00 × 10⁻⁶ C. It is positive, like the first charge, because the force is repulsive.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eb15c66f-9283-5071-8823-41644329c0fe', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 55, 55, 'Two identical small plastic spheres are 0.15 m apart and repel each other with a force of 0.050 N. The charges on them are equal. Calculate the magnitude of the charge on each sphere, in coulombs. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 3, 'numeric'::answer_type, '3.536e-7', 'C', 0.05, false, 'With q₁ = q₂ = q, F = kq²/r², so q = √(F r²/k) = √(0.050 × 0.15² ÷ 9.0 × 10⁹) = √(1.25 × 10⁻¹³) = 3.54 × 10⁻⁷ C.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('134603e1-5f6e-508c-aeea-d77bd8987800', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 56, 56, 'A charge of −1.5 × 10⁻⁶ C is 0.20 m from an unknown charge qx. The force between them is 3.375 N and it is attractive. Calculate qx in coulombs, including its sign. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 3, 'numeric'::answer_type, '1e-5', 'C', 0.05, true, 'Magnitude: |qx| = F r²/(k|q|) = (3.375 × 0.20²) ÷ (9.0 × 10⁹ × 1.5 × 10⁻⁶) = 0.135 ÷ 13500 = 1.00 × 10⁻⁵ C. The force is attractive, so qx has the opposite sign to the negative charge: qx = +1.00 × 10⁻⁵ C.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('15cb7737-b090-554d-bfd5-611a28c5fad0', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 57, 57, 'Two charges, qA and qB = −5.0 nC, are 0.030 m apart. The attractive force between them is 0.15 N. Calculate the magnitude of qA, in coulombs. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 3, 'numeric'::answer_type, '3e-6', 'C', 0.05, false, '|qA| = F r²/(k|qB|) = (0.15 × 0.030²) ÷ (9.0 × 10⁹ × 5.0 × 10⁻⁹) = 1.35 × 10⁻⁴ ÷ 45 = 3.00 × 10⁻⁶ C. (It is positive, since the force is attractive and qB is negative.)', 3) ON CONFLICT (id) DO NOTHING;
